#include <bits/stdc++.h>
using namespace std;

long long powMod(long long base, long long exp, int mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long nCr(int n, int r, vector<long long>& fact, int mod) {
    long long numerator = fact[n];
    long long denominator = (fact[r] * fact[n - r]) % mod;
    return numerator * powMod(denominator, mod - 2, mod) % mod;
}

